ALTER TABLE `#__intercom_drafts` ADD COLUMN `audience_fingerprint` varchar(64) DEFAULT NULL, ADD COLUMN `audience_rules` mediumtext DEFAULT NULL, ADD COLUMN `estimate_count` int unsigned DEFAULT NULL, ADD COLUMN `estimate_checked` datetime DEFAULT NULL, ADD COLUMN `tested_audience` varchar(64) DEFAULT NULL, ADD COLUMN `tested_count` int unsigned DEFAULT NULL, ADD COLUMN `mailing_attempted` tinyint NOT NULL DEFAULT 1, ADD COLUMN `lease_until` datetime DEFAULT NULL, ADD COLUMN `lease_generation` int unsigned NOT NULL DEFAULT 0;
ALTER TABLE `#__intercom_drafts` ALTER COLUMN `mailing_attempted` SET DEFAULT 0;
CREATE TABLE IF NOT EXISTS `#__intercom_history` (`draft_id` int unsigned NOT NULL, `revision` int unsigned NOT NULL, `actor_id` int unsigned NOT NULL, `delivery_mode` varchar(8) NOT NULL, `account_id` varchar(20) NOT NULL DEFAULT '', `group_id` int unsigned NOT NULL DEFAULT 0, `type_key` varchar(64) NOT NULL, `state` varchar(24) NOT NULL DEFAULT 'prepared', `filter_id` int unsigned DEFAULT NULL, `mailing_id` int unsigned NOT NULL DEFAULT 0, `snapshot` mediumtext DEFAULT NULL, `reconstructed` tinyint NOT NULL DEFAULT 0, `requested_at` datetime DEFAULT NULL, `scheduled_at` bigint unsigned NOT NULL DEFAULT 0, `started_at` datetime DEFAULT NULL, `finished_at` datetime DEFAULT NULL, `created_at` datetime NOT NULL, PRIMARY KEY (`draft_id`), KEY `sent` (`state`,`started_at`), KEY `requested` (`requested_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
